import{t as e}from"./client-DF22Lxer.js";var t={list(t=1,n=20){return e.get(`/downloaders`,{params:{page:t,size:n}})},listLight(t=1,n=200,r){return e.get(`/downloaders`,{params:{page:t,size:n,light:`true`,role:r}})},get(t){return e.get(`/downloaders/${t}`)},create(t){return e.post(`/downloaders`,t)},update(t,n){return e.put(`/downloaders/${t}`,n)},delete(t){return e.delete(`/downloaders/${t}`)},testConnection(t){return e.post(`/downloaders/${t}/test`)},getTorrents(t,n){return e.get(`/downloaders/${t}/torrents`,{params:n})},getTorrent(t,n){return e.get(`/downloaders/${t}/torrents/${n}`)},getFreeSpace(t){return e.get(`/downloaders/${t}/free-space`)},getMaindata(t){return e.get(`/downloaders/${t}/maindata`)},pauseTorrent(t,n){return e.post(`/downloaders/${t}/torrents/${n}/pause`)},resumeTorrent(t,n){return e.post(`/downloaders/${t}/torrents/${n}/resume`)},deleteTorrent(t,n){return e.delete(`/downloaders/${t}/torrents/${n}`)},listPublishTargets(){return e.get(`/downloaders/publish-targets`)},createPublishTarget(t){return e.post(`/downloaders/publish-targets`,t)},updatePublishTarget(t){return e.put(`/downloaders/publish-targets`,t)},deletePublishTarget(t){return e.delete(`/downloaders/publish-targets`,{data:{id:t}})}};export{t};